/* jx_bridge_exe.c -- JX-3P.exe's bridge unit: jx3p/gui/jx_bridge.c whole, then what only the program's panel calls
 * and needs the bridge's own statics for. One translation unit, so jx_bridge.c itself -- the file every product
 * gate builds -- stays as those gates graded it.
 *
 * THE OPTION MENU'S CC MAPPING (the menuButton's menu, rva 0x4147B0): "Set MIDI Control Mapping for SYSTEM-8" and
 * "Clear MIDI Control Mapping". The preset is the plugin's one table (jx3p/gui/win/jx_cc_preset.h, generated by
 * jx3p/tools/jx_gen_cc_preset.py and checked against the plugin's own apply and test); the menu's items, enables and
 * the CC map after a choice are graded by jx3p/tools/jx_panel_gate.py against the plugin's own menu (JX_PANEL.md). */
#include "../jx_bridge.c"
#include "jx_cc_preset.h"

#ifndef JX_PRESET_TOOTH  /* MUTANT (jx_panel_gate.py --bridge-tooth 1): the test reads only a record's first entry */
#define JX_PRESET_TOOTH 0
#endif
void jx3p_cc_preset(int k);
int jx3p_cc_preset_is(int k);

/* rva 0x31A3D0: every record's CC and the map cleared; with k >= 0 each record named in the preset takes the CC of
 * its first entry, in the records' order, and that CC drives it (a later record with the same CC takes it over) */
void jx3p_cc_preset(int k)
{
    int i;
    for (i = 0; i < JX_MIDI_PARAM_N; ++i) g_cc.rec[i] = -1;
    for (i = 0; i < 128; ++i) g_cc.map[i] = -1;
    if (k < 0) return;
    for (i = 0; i < JX_CC_PRESET_SET_N; ++i) {
        int e = jx_midi_entry(JX_CC_PRESET_SET[i].id), cc = JX_CC_PRESET_SET[i].cc;
        if (e < 0 || cc < 0 || cc > 127) continue;
        g_cc.rec[e] = (int8_t)cc;
        g_cc.map[cc] = (int8_t)e;
    }
}
/* rva 0x31A2B0: k < 0 -- no CC drives a record; else every record named in the preset has the CC of EACH entry
 * naming it (a record two entries name with two CCs never passes) and every other record has none */
int jx3p_cc_preset_is(int k)
{
    int e, i, named;
    if (k < 0) {
        for (i = 0; i < 128; ++i) if (g_cc.map[i] >= 0) return 0;
        return 1;
    }
    for (e = 0; e < JX_MIDI_PARAM_N; ++e) {
        named = 0;
        for (i = 0; i < JX_CC_PRESET_CHK_N; ++i)
            if (jx_midi_entry(JX_CC_PRESET_CHK[i].id) == e && !(JX_PRESET_TOOTH == 1 && named)) {
                if (g_cc.rec[e] != JX_CC_PRESET_CHK[i].cc) return 0;
                named = 1;
            }
        if (!named && g_cc.rec[e] >= 0) return 0;
    }
    return 1;
}
